mapper.update:
UPDATE t_balance_applied_fact
SET apply_status = #{status}, fact_type = #{fact.factType}, supersedes_fact_id = #{fact.supersedesFactId},
    superseded_by_fact_id = #{fact.supersededByFactId}, posting_id = #{fact.postingId},
    balance_available_time = #{fact.balanceAvailableTime}, maturity_status = #{fact.maturityStatus},
    applied_time = #{fact.appliedTime}, update_time = #{now}
WHERE id = #{fact.id} AND apply_status = #{fact.applyStatus}

mapper.select:
SELECT DISTINCT entity_no FROM t_balance_applied_fact
WHERE finance_entity_id = #{financeEntityId} AND currency = #{currency}
ORDER BY entity_no

SELECT  FROM t_balance_applied_fact
WHERE maturity_status = 'PENDING' AND balance_available_time <= #{asOf} AND id > #{afterId}
ORDER BY id
LIMIT #{limit}
